import { Fragment, useEffect } from 'react';
import { Text } from 'react-native';
import { fieldChange } from '../core/fieldChange';
import type { FieldChangeInput } from '../core/fieldChange';
import type {
  ProviderAdapter,
  ProviderFieldProps,
  ProviderHostProps,
} from '../core/ProviderAdapter';
import type { CardDetails, TokenizeResult, VaultType } from '../core/types';

export interface MockAdapterOptions {
  vaultType?: VaultType;

  readyDelayMs?: number;

  neverReady?: boolean;

  failOnInit?: unknown;

  tokenizeResult?: TokenizeResult;

  fieldState?: FieldChangeInput;

  cardDetails?: Partial<CardDetails>;

  onTokenize?: () => void;
}

export function createMockAdapter(
  options: MockAdapterOptions = {}
): ProviderAdapter {
  const vaultType: VaultType = options.vaultType ?? 'vgs';

  function Host({
    onReady,
    onError,
    onCardDetails,
    children,
  }: ProviderHostProps) {
    useEffect(() => {
      if (options.failOnInit !== undefined) {
        onError(options.failOnInit);
        return;
      }
      if (options.neverReady) return;

      const delay = options.readyDelayMs ?? 0;
      const timer = setTimeout(() => {
        onReady({ mock: true });
        if (options.cardDetails) onCardDetails?.(options.cardDetails);
      }, delay);
      return () => clearTimeout(timer);
    }, [onReady, onError, onCardDetails]);

    return <Fragment>{children}</Fragment>;
  }

  function Field({
    elementType,
    onChange,
    styles,
    savedCard,
    placeholder,
    cvcIcon,
    cardBrandIcon,
    label,
    labelBehavior,
    errorDisplay,
    unstyled,
  }: ProviderFieldProps) {
    const state = options.fieldState;
    useEffect(() => {
      if (state) onChange?.(fieldChange(elementType, state));
    }, [elementType, onChange, state]);
    return (
      <Text
        testID={`mock-field-${elementType}`}
        style={styles?.container}
        accessibilityLabel={
          savedCard
            ? `saved:${savedCard.paymentMethodToken}:${savedCard.paymentMethodData?.card?.cardNetwork ?? ''}`
            : undefined
        }
        accessibilityHint={cvcIcon}
        accessibilityValue={{
          /* Every forwarded prop, for tests to read back; JSON drops the unset ones. */
          text: JSON.stringify({
            placeholder,
            cardBrandIcon,
            label,
            labelBehavior,
            errorDisplay,
            unstyled,
          }),
        }}
      >{`mock:${elementType}`}</Text>
    );
  }

  return {
    vaultType,
    validateVaultData: (raw) => raw,
    createCollector: async () => {
      if (options.failOnInit !== undefined) throw options.failOnInit;
      if (options.readyDelayMs) {
        await new Promise((resolve) =>
          setTimeout(resolve, options.readyDelayMs)
        );
      }
      return { mock: true };
    },
    Host,
    Field,
    tokenize: async () => {
      options.onTokenize?.();
      return (
        options.tokenizeResult ?? {
          status: 'success',
          vaultType,
          data: { tokens: { card_number: 'tok_mock' } },
        }
      );
    },
  };
}

import { describe, it, expect, jest } from '@jest/globals';
import { HyperswitchPaymentMethods } from '../HyperswitchPaymentMethods';
import { registerForm } from '../core/formRegistry';
import type { TokenizeResult } from '../core/types';

const ok: TokenizeResult = { status: 'success', vaultType: 'skyflow' };

describe('HyperswitchPaymentMethods.tokenize', () => {
  it('answers incomplete_field_set when no form is registered for the id', async () => {
    const result = await HyperswitchPaymentMethods.tokenize('absent');
    expect(result.status).toBe('validation_error');
    expect(result.status === 'validation_error' && result.error).toEqual({
      code: 'incomplete_field_set',
      message: expect.stringContaining('<CardForm id="absent">'),
      type: 'validation_error',
    });
  });

  it('routes to the registered form and forwards providerData', async () => {
    const tokenize = jest.fn(async () => ok);
    const off = registerForm('checkout', tokenize);
    try {
      const result = await HyperswitchPaymentMethods.tokenize('checkout', {
        token: 'abc',
      });
      expect(tokenize).toHaveBeenCalledWith({ token: 'abc' });
      expect(result).toEqual(ok);
    } finally {
      off();
    }
  });
});

