      expect.stringContaining('options.cvcIcon')
    );

    warn.mockClear();
    screen.unmount();
    render(
      <CardForm vaultDetails={details}>
        <CardNumberField options={{ cardBrandIcon: loose('') }} />
        <CardCVCField cvcIcon={loose('')} options={{ cvcIcon: loose(null) }} />
