      ],
      [
        { publishableKey: 'pk_prd_x', environment: 'PROD_EU' },
        'https://eu.hyperswitch.io/api',
      ],
      [
        { publishableKey: 'pk_snd_x', environment: 'INTEG' },
        'https://integ.hyperswitch.io/api',
      ],
      [
        { publishableKey: 'pk_prd_x', environment: 'production' },
        'https://live.hyperswitch.io/api',
      ],
      [
        {
          publishableKey: 'pk_prd_x',
          environment: 'SANDBOX',
          customEndpoints: { commonEndpoint: 'https://eu.hyperswitch.io/api' },
        },
        'https://eu.hyperswitch.io/api',
      ],
    ];

    for (const [config, base] of cases) {
      fetchMock.mockClear();
      const view = render(
        <HyperPaymentMethodSession
          hyper={config as never}
          options={{ sdkAuthorization: VALID_AUTH }}
        >
          <VaultProbe />
        </HyperPaymentMethodSession>
      );
      await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
      expect(fetchMock.mock.calls[0]![0]).toBe(
        `${base}/v1/payment-method-sessions/0a_pms_0192`
      );
      view.unmount();
    }
  });

  it('skips the lookup entirely when vaultDetails is supplied too', async () => {
    installMock({ vaultType: 'skyflow' });
    const ref = createRef<CardFormHandle>();

    render(
      <HyperPaymentMethodSession
        hyper={hyper}
        options={{
          sdkAuthorization: VALID_AUTH,
          vaultDetails: details('skyflow'),
        }}
      >
        <CardForm ref={ref}>
          <CardNumberField />
        </CardForm>
      </HyperPaymentMethodSession>
    );

    await waitFor(() =>
      expect(screen.getByTestId('mock-field-cardNumber')).toBeTruthy()
    );
    expect((await tokenizeVia(ref))?.vaultType).toBe('skyflow');
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('answers sdk_not_ready while the lookup is still in flight', async () => {
    installMock({ vaultType: 'vgs' });

    fetchMock.mockImplementation(
      (_url, init) =>
        new Promise((_resolve, reject) => {
          const signal = (init as { signal?: AbortSignal } | undefined)?.signal;
          signal?.addEventListener('abort', () => reject(new Error('aborted')));
        })
    );
    const ref = createRef<CardFormHandle>();

    render(
      <HyperPaymentMethodSession
        hyper={hyper}
        options={{ sdkAuthorization: VALID_AUTH }}
      >
        <VaultProbe />
        <CardForm ref={ref}>
          <CardNumberField />
        </CardForm>
      </HyperPaymentMethodSession>
    );

    await waitFor(() =>
      expect(screen.getByTestId('vault').props.children).toBe('none:true:')
    );

    const result = await tokenizeVia(ref);
    expect(result?.status).toBe('error');
    expect(errorOf(result)?.code).toBe('sdk_not_ready');
  });

  it('reports a failed lookup, and says why when tokenize is called', async () => {
    installMock({ vaultType: 'vgs' });
    fetchMock.mockResolvedValue({
      ok: false,
      status: 401,
      json: async () => ({}),
    });
    const onError = jest.fn();
    const ref = createRef<CardFormHandle>();

    render(
      <HyperPaymentMethodSession
        hyper={hyper}
        options={{ sdkAuthorization: VALID_AUTH }}
        onError={onError}
      >
        <VaultProbe />
        <CardForm ref={ref}>
          <CardNumberField />
        </CardForm>
      </HyperPaymentMethodSession>
    );

    await waitFor(() =>
      expect(screen.getByTestId('vault').props.children).toBe(
        'none:false:The payment-method-session lookup returned status 401.'
      )
    );
    expect(onError).toHaveBeenCalledTimes(1);

    const result = await tokenizeVia(ref);
    expect(errorOf(result)?.code).toBe('unsupported_configuration');
    expect(errorOf(result)?.message).toMatch(/status 401/);
  });
});

import {
  describe,
  it,
  expect,
  jest,
  beforeEach,
  afterEach,
} from '@jest/globals';

import { fetchVaultDetails, readVaultDetails } from '../fetchVaultDetails';
import { decodeBase64, readAuthorizationClaims } from '../sdkAuthorization';

const authorization = (claims: string) =>
  Buffer.from(claims, 'utf8').toString('base64');

const VALID_AUTH = authorization(
  'payment_method_session_id=0a_pms_0192,profile_id=pro_456'
);

type FetchArgs = [string, { headers?: Record<string, string> }];

const okResponse = (body: unknown) => ({
  ok: true,
  status: 200,
  json: async () => body,
});

const sessionBody = (external: unknown) => ({
  id: '0a_pms_0192',
  client_secret: 'cs_9wcXDRVkfEtLEsSnYKgQ',
  external_vault_details: external,
});

const original = globalThis.fetch;
let fetchMock: jest.Mock<(...args: FetchArgs) => Promise<unknown>>;

beforeEach(() => {
  fetchMock = jest.fn<(...args: FetchArgs) => Promise<unknown>>();
  (globalThis as { fetch?: unknown }).fetch = fetchMock;
});

afterEach(() => {
  (globalThis as { fetch?: unknown }).fetch = original;
});

describe('sdkAuthorization', () => {
  it('decodes base64, including the URL-safe alphabet and missing padding', () => {
    expect(decodeBase64('cHJvZmlsZV9pZD0uLi4=')).toBe('profile_id=...');
    expect(decodeBase64('cHJvZmlsZV9pZD0uLi4')).toBe('profile_id=...');
    expect(decodeBase64('!!not base64!!')).toBeUndefined();
  });

  it('reads the session id out of the claims', () => {
    const result = readAuthorizationClaims(VALID_AUTH);
    expect(result.ok && result.claims).toEqual({
      paymentMethodSessionId: '0a_pms_0192',
    });
  });

  it('names what is missing', () => {
    expect(readAuthorizationClaims('   ')).toEqual({
      ok: false,
      message: 'sdkAuthorization is empty.',
    });
    expect(readAuthorizationClaims('!!!')).toEqual({
      ok: false,
      message: 'sdkAuthorization is not valid base64.',
    });

    const noSession = readAuthorizationClaims(
      authorization('profile_id=pro_1')
    );
    expect(noSession.ok).toBe(false);
    expect(!noSession.ok && noSession.message).toMatch(
      /payment_method_session_id/
    );
  });
});

describe('readVaultDetails', () => {
  it('maps the documented VGS shape onto VgsVaultData', () => {
    const result = readVaultDetails(
      sessionBody({ vgs: { external_vault_id: 'tnt_abc', sdk_env: 'sandbox' } })
    );
    expect(result).toEqual({
      ok: true,
      vaultDetails: {
        vaultType: 'vgs',
        vaultData: { vaultId: 'tnt_abc', environment: 'sandbox' },
      },
    });
  });

  it('reads the Hyperswitch vault off vault_details, ahead of external', () => {
    const result = readVaultDetails({
      id: '0a_pms_0192',
      vault_details: {
        vault_type: 'hyperswitch',
        vault_data: { sdk_authorization: 'auth_123' },
      },
      external_vault_details: {
        vgs: { external_vault_id: 'tnt_abc', sdk_env: 'sandbox' },
      },
    });
    expect(result).toEqual({
      ok: true,
      vaultDetails: {
        vaultType: 'hyperswitch',
        vaultData: { sdkAuthorization: 'auth_123' },
      },
    });
  });

  it('falls through to external_vault_details when vault_details names another vault', () => {
    const result = readVaultDetails({
      vault_details: { vault_type: 'something_else', vault_data: {} },
      external_vault_details: {
        vgs: { external_vault_id: 'tnt_abc', sdk_env: 'sandbox' },
      },
    });
    expect(result.ok && result.vaultDetails.vaultType).toBe('vgs');
  });

  it('camelizes any other supported vault it is handed', () => {
    const result = readVaultDetails(
      sessionBody({
        skyflow: { vault_id: 'v1', vault_url: 'https://x', table: 't' },
      })
    );
    expect(result).toEqual({
      ok: true,
      vaultDetails: {
        vaultType: 'skyflow',
        vaultData: { vaultId: 'v1', vaultUrl: 'https://x', table: 't' },
      },
    });
  });

  it('says so when the session names no supported vault', () => {
    const missing = readVaultDetails(sessionBody(undefined));
    expect(missing.ok).toBe(false);
    expect(!missing.ok && missing.message).toMatch(/names no vault/);

    const unknown = readVaultDetails(sessionBody({ some_other_vault: {} }));
    expect(unknown.ok).toBe(false);
    expect(!unknown.ok && unknown.message).toMatch(/some_other_vault/);
  });
});

describe('fetchVaultDetails', () => {
  it('GETs the payment-method session with the authorization header', async () => {
    fetchMock.mockResolvedValue(
      okResponse(
        sessionBody({
          vgs: { external_vault_id: 'tnt_abc', sdk_env: 'sandbox' },
        })
      )
    );

    const result = await fetchVaultDetails({ sdkAuthorization: VALID_AUTH });

    expect(result.ok && result.vaultDetails.vaultType).toBe('vgs');
    const [url, init] = fetchMock.mock.calls[0]!;

    expect(url).toBe(
      'https://live.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );
    expect(init.headers).toMatchObject({ Authorization: VALID_AUTH });
    expect('X-Profile-Id' in (init.headers ?? {})).toBe(false);
  });

  it('uses the SANDBOX host when asked for it', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'SANDBOX',
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://app.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('uses the EU host for PROD_EU', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'PROD_EU',
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://eu.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('uses the INTEG host when asked for it, as the vault does', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'INTEG',
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://integ.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('treats an unrecognised environment as PROD', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'production' as never,
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://live.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('refuses a blank or disallowed backend without calling the network', async () => {
    for (const customEndpoints of [
      { commonEndpoint: '  ' },
      { overrideEndpoints: { customBackendEndpoint: '' } },
      { commonEndpoint: 'http://proxy.acme.test/api' },
      { commonEndpoint: 'http://localhost:8080/api' },
      { commonEndpoint: 'https://user:pass@vault.acme.test/api' },
      { commonEndpoint: 'https://vault.acme.test/api?key=1' },
      { commonEndpoint: 'https://vault.acme.test/api#key' },
    ]) {
      const result = await fetchVaultDetails({
        sdkAuthorization: VALID_AUTH,
        environment: 'PROD',
        customEndpoints,
      });
      expect(result.ok).toBe(false);
      expect(!result.ok && result.message).toMatch(/blank or not allowed/);
    }
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('reads malformed customEndpoints from JavaScript as absent instead of throwing', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    for (const customEndpoints of [
      {},
      { overrideEndpoints: undefined },
      { overrideEndpoints: null },
      { commonEndpoint: 42 },
      'https://vault.acme.test',
    ]) {
      fetchMock.mockClear();
      const result = await fetchVaultDetails({
        sdkAuthorization: VALID_AUTH,
        customEndpoints: customEndpoints as never,
      });
      expect(result.ok).toBe(true);
      expect(fetchMock.mock.calls[0]![0]).toBe(
        'https://live.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
      );
    }
  });

  it('allows http to localhost outside PROD, as the vault does', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'SANDBOX',
      customEndpoints: { commonEndpoint: 'http://localhost:8080/api/' },
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'http://localhost:8080/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it("takes commonEndpoint ahead of an override, in the vault's order", async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      customEndpoints: {
        commonEndpoint: 'https://vault.acme.test/api',
        overrideEndpoints: { customBackendEndpoint: 'https://other.acme.test' },
      } as never,
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://vault.acme.test/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('reads an overrideEndpoints backend endpoint', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );
    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'INTEG',
      customEndpoints: {
        overrideEndpoints: { customBackendEndpoint: 'https://integ.acme.test' },
      },
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://integ.acme.test/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('uses the PROD host and explicit customEndpoints', async () => {
    fetchMock.mockResolvedValue(
      okResponse(sessionBody({ vgs: { external_vault_id: 'x' } }))
    );

    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'PROD',
    });
    expect(fetchMock.mock.calls[0]![0]).toBe(
      'https://live.hyperswitch.io/api/v1/payment-method-sessions/0a_pms_0192'
    );

    await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
      environment: 'PROD',
      customEndpoints: { commonEndpoint: 'https://vault.acme.test/api/' },
    });
    expect(fetchMock.mock.calls[1]![0]).toBe(
      'https://vault.acme.test/api/v1/payment-method-sessions/0a_pms_0192'
    );
  });

  it('never throws: a non-2xx, unreadable body, or a thrown fetch all come back as a result', async () => {
    fetchMock.mockResolvedValue({
      ok: false,
      status: 401,
      json: async () => ({}),
    });
    const unauthorized = await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
    });
    expect(unauthorized).toEqual({
      ok: false,
      message: 'The payment-method-session lookup returned status 401.',
    });

    fetchMock.mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => {
        throw new Error('bad json');
      },
    });
    const unreadable = await fetchVaultDetails({
      sdkAuthorization: VALID_AUTH,
    });
    expect(unreadable.ok).toBe(false);
    expect(!unreadable.ok && unreadable.message).toMatch(/readable JSON/);

    fetchMock.mockRejectedValue(new Error('network down'));
    const offline = await fetchVaultDetails({ sdkAuthorization: VALID_AUTH });
    expect(offline).toEqual({ ok: false, message: 'network down' });
  });

  it('does not call the network when the authorization carries no session id', async () => {
    const result = await fetchVaultDetails({
      sdkAuthorization: authorization('profile_id=pro_1'),
    });
    expect(result.ok).toBe(false);
    expect(fetchMock).not.toHaveBeenCalled();
  });
});

